// Inputs arrive merged by position from the 3 parallel agent branches
const items = $input.all();

// Each item corresponds to one branch's agent output, in the order the Merge node received them
// items[0] = Sentiment, items[1] = Feature Mentions, items[2] = Complaint Category
const getOutput = (item) => (item.json.output || item.json.text || '').toString();

const sentimentRaw = getOutput(items[0]);
const featuresRaw = getOutput(items[1]);
const complaintRaw = getOutput(items[2]);

function parseField(text, label) {
  const regex = new RegExp(label + '\s*:\s*(.+)', 'i');
  const match = text.match(regex);
  return match ? match[1].trim() : '';
}

const sentiment = parseField(sentimentRaw, 'Sentiment');
const sentimentScore = parseField(sentimentRaw, 'Sentiment Score');
const sentimentReasoning = parseField(sentimentRaw, 'Reasoning');

const featuresMentioned = parseField(featuresRaw, 'Features Mentioned');
const primaryFeature = parseField(featuresRaw, 'Primary Feature');

const hasComplaint = parseField(complaintRaw, 'Has Complaint');
const complaintCategory = parseField(complaintRaw, 'Complaint Category');
const severity = parseField(complaintRaw, 'Severity');

const reviewText = $('Set Review Text').first().json.reviewText;

return [{
  json: {
    review_text: reviewText,
    sentiment: sentiment,
    sentiment_score: sentimentScore,
    sentiment_reasoning: sentimentReasoning,
    features_mentioned: featuresMentioned,
    primary_feature: primaryFeature,
    has_complaint: hasComplaint,
    complaint_category: complaintCategory,
    severity: severity,
    analyzed_at: new Date().toISOString()
  }
}];
